    def _get_headers(self, pretty: bool = False) -> Dict[str, str]:
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Accept": "application/json",
            "Content-Type": "application/json"
        }
        if pretty:
            headers["X-Asana-Pretty"] = "true"
        return headers

    def update_section(self, section_gid: str, data: Dict[str, Any], opt_fields: str = None, opt_pretty: bool = False) -> Dict[str, Any]:
