from fastapi import APIRouter, HTTPException, Depends, Body, Request
from .service import AsanaService
from .client import AsanaClient
from typing import Dict, Any

router = APIRouter(prefix='/asana', tags=['asana'])

async def get_asana_service(request: Request):
    api_key = request.headers.get('Authorization', None)
    if not api_key:
        raise HTTPException(status_code=401, detail='Authorization header missing')
    return AsanaService(AsanaClient(api_key))

@router.put('/sections/{section_gid}')
async def update_section(
        section_gid: str,
        params: Dict[str, Any] = Body(...),
        service: AsanaService = Depends(get_asana_service)
    ) -> Any:
    try:
        return service.update_section(section_gid, params.get('name'), params.get('opt_fields'), params.get('opt_pretty', False))
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@router.post('/projects/{project_gid}/removeCustomFieldSetting')
async def remove_custom_field_setting(
        project_gid: str,
        service: AsanaService = Depends(get_asana_service)
    ) -> Any:
    try:
        return service.remove_custom_field_setting(project_gid)
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@router.get('/project_briefs')
async def project_briefs(
        service: AsanaService = Depends(get_asana_service)
    ) -> Any:
    try:
        return service.project_briefs()
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@router.post('/projects/{project_gid}/saveAsTemplate')
async def project_save_as_template(
        project_gid: str,
        service: AsanaService = Depends(get_asana_service)
    ) -> Any:
    try:
        return service.project_save_as_template(project_gid)
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@router.post('/project_templates/{project_template_gid}/instantiateProject')
async def instantiate_project(
        project_template_gid: str,
        params: Dict[str, Any] = Body(...),
        service: AsanaService = Depends(get_asana_service)
    ) -> Any:
    try:
        return service.instantiate_project(project_template_gid, params.get('name'), params.get('team_gid'), params.get('opt_fields'), params.get('opt_pretty', False))
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@router.post('/projects/{project_gid}/duplicate')
