        service: AsanaService = Depends(get_asana_service)
    ) -> Any:
    try:
        return service.get_project(project_gid, params.get('opt_fields'), params.get('opt_pretty', False))
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@router.put('/projects/{project_gid}')
